/* 麻燕叫声与古琴录音。容器禁止 <audio> 走 data:，所以这里不是媒体元素：
   app.js 用 atob 转 ArrayBuffer 后交给 decodeAudioData，走的是 Web Audio，
   全程没有资源加载。来源与授权见 index.html 末尾的注释。 */
window.AUD={"music_xiao": "data:audio/mpeg;base64,", "music_qin": "data:audio/mpeg;base64,", "swift_a": "data:audio/mpeg;base64,", "swift_b": "data:audio/mpeg;base64,", "swift_c": "data:audio/mpeg;base64,", "swift_d": "data:audio/mpeg;base64,", "swift_e": "data:audio/mpeg;base64,", "swift_f": "data:audio/mpeg;base64,", "swift_g": "data:audio/mpeg;base64,"};
